using System;using System.Linq;using System.Reflection;
var asm = typeof(Markout.MarkoutSerializer).Assembly;
foreach(var t in asm.GetExportedTypes().OrderBy(x=>x.Name)){
  if(!t.Name.StartsWith("Markout"))continue;
  if(!typeof(Attribute).IsAssignableFrom(t))continue;
