[MarkoutSerializable(TitleProperty = nameof(Id))]
public sealed class PackageReport
{
    public string Id { get; init; } = "";
    public string Version { get; init; } = "";
    public int DeprecationCount { get; init; }

    [MarkoutSection(Name = "Deprecations", ShowWhenProperty = nameof(HasDeprecations))]
    public List<DeprecationRow>? Deprecations { get; init; }

    public bool HasDeprecations => Deprecations is { Count: > 0 };

    public static PackageReport From(PackageInfo package) => new()
    {
        Id = package.Id,
        Version = package.Version,
        DeprecationCount = package.Deprecations.Count,
        Deprecations = package.Deprecations.Select(d => new DeprecationRow { Notice = d }).ToList(),
    };
}

