void Render(string label, HashSet<string> sections)
{
    Console.WriteLine($"===== {label} =====");
    var options = new MarkoutWriterOptions { IncludeSections = sections };
    MarkoutSerializer.Serialize(pkg, Console.Out, new MarkdownFormatter(), ReportContext.Default, options);
    Console.WriteLine();
}

